contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        // fund c: this contract is the Owner of c
        c.Command{value: amount}(address(this), ""); if (__ESBMC_reverted()) return;
        require(address(c).balance >= amount);
        uint256 before = address(c).balance;
        // owner withdraws everything
        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(!reverted && address(c).balance == 0);
    }
    receive() external payable {}
}

